cg3::BoundingBox3 bbox;
if (points.empty()) {
    return bbox;
}
double minX = std::numeric_limits<double>::max();
double minY = std::numeric_limits<double>::max();
double minZ = std::numeric_limits<double>::max();
double maxX = std::numeric_limits<double>::min();
double maxY = std::numeric_limits<double>::min();
double maxZ = std::numeric_limits<double>::min();
for (const auto& point : points) {
    if (point.x() < minX) {
        minX = point.x();
    }
    if (point.y() < minY) {
        minY = point.y();
    }
    if (point.z() < minZ) {
        minZ = point.z();
    }
    if (point.x() > maxX) {
        maxX = point.x();
    }
    if (point.y() > maxY) {
        maxY = point.y();
    }
    if (point.z() > maxZ) {
        maxZ = point.z();
    }
}
cg3::Point3d minPoint(minX, minY, minZ);
cg3::Point3d maxPoint(maxX, maxY, maxZ);
bbox = cg3::BoundingBox3(minPoint, maxPoint);
return bbox;

